    <section class="scheduler-section" aria-labelledby="subjects-heading"><header><span>02</span><div><h3 id="subjects-heading">Batch-wise written papers</h3><p>Subjects stay separated by branch, admission batch, semester, and section.</p></div></header><fieldset class="subject-scope"><legend class="visually-hidden">Select written subjects</legend><input type="hidden" name="subject_selection_active" value="1"><div class="subject-notice"><i class="ti ti-flask-off" aria-hidden="true"></i><p>Labs and practicals are excluded automatically. All matching batch-wise written papers start selected.</p></div><div class="subject-scope-tools"><label><span>Filter by branch</span><select id="subject-branch-filter"><option value="">All selected branches</option><?php foreach($programmes as $programme):?><option value="<?= (int)$programme['id'] ?>"><?= e($programme['code'].' | '.$programme['name']) ?></option><?php endforeach;?></select></label><label><span>Filter by batch</span><select id="subject-batch-filter"><option value="">All selected batches</option><?php foreach($cycleBatches as $batch):?><option value="<?= (int)$batch['id'] ?>" data-programme="<?= (int)$batch['programme_id'] ?>"><?= e($batch['label']) ?></option><?php endforeach;?></select></label><span class="subject-total"><b id="selected-subject-count">0</b> of <b id="available-subject-count">0</b> papers selected</span><button type="button" id="select-visible-subjects"><i class="ti ti-checks" aria-hidden="true"></i> Select shown</button><button type="button" id="clear-visible-subjects"><i class="ti ti-square" aria-hidden="true"></i> Clear shown</button></div><div id="scheduler-subjects" class="subject-choice-list"><?php foreach($curriculum as $subject):?><label data-programme="<?= (int)$subject['programme_id'] ?>" data-batch="<?= (int)($subject['batch_id']??0) ?>" data-semester="<?= (int)$subject['semester'] ?>" hidden><input type="checkbox" name="programme_course_ids[]" value="<?= (int)$subject['id'] ?>" data-initialized="<?= $savedSubjectSelection?'1':'0' ?>" <?= $savedSubjectSelection&&in_array((int)$subject['id'],$savedSubjectIds,true)?'checked':'' ?> disabled><span><strong><?= e($subject['code']) ?></strong><small><?= e($subject['name']) ?></small><em><b><?= e($subject['programme_code']) ?></b><b><?= e($subject['batch_label']?:'Legacy curriculum') ?></b><b>Semester <?= (int)$subject['semester'] ?></b><b>Section <?= e($subject['section']) ?></b><b>Priority <?= (int)$subject['subject_priority'] ?></b></em></span></label><?php endforeach;?></div><div id="subject-scope-empty" class="generator-inline-empty"><i class="ti ti-books" aria-hidden="true"></i><strong>No papers to display yet</strong><span>Select a branch, batch, and semester to load eligible written subjects.</span></div></fieldset></section>
    <section class="scheduler-section" aria-labelledby="rules-heading"><header><span>03</span><div><h3 id="rules-heading">Scheduling preferences</h3><p>Set preferred spacing. The engine relaxes preferences only when necessary to place every valid paper.</p></div></header><div class="rule-grid"><label><span>Preferred rest gap</span><div class="input-suffix"><input type="number" name="minimum_gap_days" min="0" max="14" value="<?= (int)($selection['minimum_gap_days']??1) ?>" required><b>days</b></div><small>Free calendar days requested between papers of the same branch.</small></label><label><span>Preferred daily limit</span><select name="maximum_papers_per_day"><?php for($limit=1;$limit<=3;$limit++):?><option value="<?= $limit ?>" <?= (int)($selection['maximum_papers_per_day']??1)===$limit?'selected':'' ?>><?= $limit ?> paper<?= $limit>1?'s':'' ?> per cohort</option><?php endfor;?></select><small>Additional configured shifts are used only when required.</small></label></div>
    <div class="rule-switches"><label><input type="checkbox" name="use_subject_priority" value="1" <?= !array_key_exists('use_subject_priority',$selection)||!empty($selection['use_subject_priority'])?'checked':'' ?>><span><i class="ti ti-sort-ascending" aria-hidden="true"></i><span><strong>Use subject priority</strong><small>Place high-priority subjects earlier and preserve their available rest gaps.</small></span></span></label><label><input type="checkbox" name="avoid_consecutive_days" value="1" <?= !array_key_exists('avoid_consecutive_days',$selection)||!empty($selection['avoid_consecutive_days'])?'checked':'' ?>><span><i class="ti ti-calendar-pause" aria-hidden="true"></i><span><strong>Prefer non-consecutive days</strong><small>Keep a free day where capacity permits without leaving a paper unscheduled.</small></span></span></label></div></section>
    <footer class="scheduler-form-footer"><div><i class="ti ti-lock-check" aria-hidden="true"></i><span><strong>Safe preview</strong><small>This step does not change or publish the date sheet.</small></span></div><button class="primary-button scheduler-submit"><i class="ti ti-shield-check" aria-hidden="true"></i> Save validation</button></footer>
  </form>
