    <div id="live-validation" class="validation-live" hidden></div>
    <div id="saved-validation">
    <?php if(!$result):?><div class="validation-empty"><div class="validation-empty-icon"><i class="ti ti-clipboard-check" aria-hidden="true"></i></div><h2>Configure your schedule</h2><p>Select the school, branches, semesters and papers. Curriculum, calendar, shifts and capacity will be checked here in real time.</p><ul><li><i class="ti ti-check" aria-hidden="true"></i> No data is changed during preview</li><li><i class="ti ti-check" aria-hidden="true"></i> Labs are excluded automatically</li><li><i class="ti ti-check" aria-hidden="true"></i> Existing papers are preserved</li></ul></div>
    <?php else:?><header class="validation-summary <?= e($result['status']) ?>"><div><p class="eyebrow">Saved validation run #<?= (int)$result['run_id'] ?></p><h2><?= $result['blocked']?'Changes required':'Ready to generate' ?></h2><p><?= (int)$result['blocked'] ?> blocked <span aria-hidden="true">·</span> <?= (int)$result['warnings'] ?> warnings</p></div><i class="ti <?= $result['blocked']?'ti-circle-x':'ti-circle-check' ?>" aria-hidden="true"></i></header>
      <?php foreach(['Academic','Calendar','Feasibility'] as $group):?><div class="validation-group"><h3><?= e($group) ?></h3><?php foreach($result['checks'] as $check):if($check['group']!==$group)continue;?><article class="validation-check <?= e($check['state']) ?>"><i class="ti <?= $check['state']==='pass'?'ti-check':($check['state']==='warning'?'ti-alert-triangle':'ti-x') ?>"></i><div><strong><?= e(strtoupper($check['state'])) ?></strong><p><?= e($check['message']) ?></p></div></article><?php endforeach;?></div><?php endforeach;?>
      <?php if(!$result['blocked']):?><form method="post" action="<?= e(url('date-sheets/'.$cycle['id'].'/automatic/generate')) ?>" class="generate-draft-form"><?= csrf_field() ?><input type="hidden" name="run_id" value="<?= (int)$result['run_id'] ?>"><button class="primary-button"><i class="ti ti-wand"></i> Generate deterministic draft</button><p>This creates draft examinations only. Nothing is published.</p></form><?php else:?><button class="primary-button" disabled><i class="ti ti-lock"></i> Resolve blocked checks first</button><?php endif;?><?php endif;?>
    </div>
  </section></aside>
</div>
</div>
<script>(()=>{const form=document.getElementById('scheduler-form'),school=document.getElementById('scheduler-school'),items=[...document.querySelectorAll('#scheduler-programmes [data-school]')],subjects=[...document.querySelectorAll('#scheduler-subjects [data-programme]')],branchFilter=document.getElementById('subject-branch-filter'),selectedCount=document.getElementById('selected-subject-count'),availableCount=document.getElementById('available-subject-count'),programmeCount=document.getElementById('selected-programme-count'),semesterCount=document.getElementById('selected-semester-count'),scopeSummary=document.getElementById('scope-selection-summary'),subjectEmpty=document.getElementById('subject-scope-empty'),live=document.getElementById('live-validation'),saved=document.getElementById('saved-validation');let timer,controller,version=0;const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));function selectedValues(name){return new Set([...form.querySelectorAll('input[name="'+name+'[]"]:checked')].map(input=>input.value));}function syncSubjects(){const programmes=selectedValues('programme_ids'),semesters=selectedValues('semesters');let available=0,selected=0;subjects.forEach(label=>{const input=label.querySelector('input'),eligible=programmes.has(label.dataset.programme)&&semesters.has(label.dataset.semester);input.disabled=!eligible;if(eligible&&input.dataset.initialized!=='1'){input.checked=true;input.dataset.initialized='1';}if(eligible){available++;if(input.checked)selected++;}label.hidden=!eligible||(branchFilter.value!==''&&label.dataset.programme!==branchFilter.value);});availableCount.textContent=available;selectedCount.textContent=selected;programmeCount.textContent=programmes.size+' selected';semesterCount.textContent=semesters.size+' selected';scopeSummary.textContent=programmes.size&&semesters.size?programmes.size+' branch'+(programmes.size===1?'':'es')+', '+semesters.size+' semester'+(semesters.size===1?'':'s')+', '+selected+' paper'+(selected===1?'':'s'):'Select the academic scope';subjectEmpty.hidden=available>0;}function sync(clear){items.forEach(item=>{const show=item.dataset.school===school.value;item.hidden=!show;if(clear&&!show)item.querySelector('input').checked=false;});[...branchFilter.options].forEach((option,index)=>{if(index===0)return;const branch=items.find(item=>item.querySelector('input').value===option.value);option.hidden=!branch||branch.hidden||!branch.querySelector('input').checked;});if(branchFilter.selectedOptions[0]?.hidden)branchFilter.value='';syncSubjects();}function render(result){const groups=['Academic','Calendar','Feasibility'];live.innerHTML='<header class="validation-summary '+escape(result.status)+'"><div><p class="eyebrow">Live preview <span aria-hidden="true">·</span> unsaved</p><h2>'+(result.blocked?'Changes needed':'Ready to save validation')+'</h2><p>'+result.blocked+' blocked <span aria-hidden="true">·</span> '+result.warnings+' warnings</p></div><i class="ti '+(result.blocked?'ti-circle-x':'ti-circle-check')+'" aria-hidden="true"></i></header>'+groups.map(group=>'<div class="validation-group"><h3>'+group+'</h3>'+result.checks.filter(check=>check.group===group).map(check=>'<article class="validation-check '+escape(check.state)+'"><i class="ti '+(check.state==='pass'?'ti-check':check.state==='warning'?'ti-alert-triangle':'ti-x')+'" aria-hidden="true"></i><div><strong>'+escape(check.state.toUpperCase())+'</strong><p>'+escape(check.message)+'</p></div></article>').join('')+'</div>').join('')+'<p class="validation-live-note"><i class="ti ti-info-circle" aria-hidden="true"></i> This preview uses the papers currently selected. Save validation to generate this exact scope.</p>';}
function update(){sync(false);clearTimeout(timer);if(controller)controller.abort();version++;saved.hidden=true;live.hidden=false;if(!school.value||!form.querySelector('input[name="programme_ids[]"]:checked')||!form.querySelector('input[name="semesters[]"]:checked')){live.innerHTML='<div class="validation-empty"><h2>Choose a school, programme and semester</h2><p>Subjects and checks will update as you edit the form.</p></div>';return;}if(!form.querySelector('input[name="programme_course_ids[]"]:checked:not(:disabled)')){live.innerHTML='<div class="validation-empty"><h2>Select at least one written subject</h2><p>You can select subjects separately for every branch and semester.</p></div>';return;}const current=version;live.innerHTML='<div class="validation-empty"><h2>Checking selected subjects…</h2></div>';timer=setTimeout(async()=>{controller=new AbortController();try{const response=await fetch(form.dataset.previewUrl,{method:'POST',body:new FormData(form),credentials:'same-origin',signal:controller.signal,headers:{'Accept':'application/json'}});const data=await response.json();if(current!==version)return;if(!response.ok)throw new Error(data.error||'Validation could not be completed.');render(data);}catch(error){if(error.name!=='AbortError'&&current===version)live.innerHTML='<div class="validation-empty"><h2>Validation unavailable</h2><p>'+escape(error.message)+'</p></div>'; }},300);}school.addEventListener('change',()=>{sync(true);update();});form.addEventListener('change',event=>{if(event.target===branchFilter)return;if(event.target.matches('input[name="programme_course_ids[]"]'))event.target.dataset.initialized='1';update();});form.addEventListener('input',event=>{if(event.target.name==='minimum_gap_days')update();});branchFilter.addEventListener('change',syncSubjects);document.getElementById('select-visible-subjects').addEventListener('click',()=>{subjects.filter(label=>!label.hidden).forEach(label=>{const input=label.querySelector('input');input.checked=true;input.dataset.initialized='1';});update();});document.getElementById('clear-visible-subjects').addEventListener('click',()=>{subjects.filter(label=>!label.hidden).forEach(label=>{const input=label.querySelector('input');input.checked=false;input.dataset.initialized='1';});update();});sync(false);})();</script>
<script>(()=>{const form=document.getElementById('scheduler-form'),programmeInputs=[...form.querySelectorAll('input[name="programme_ids[]"]')],batchInputs=[...form.querySelectorAll('input[name="batch_ids[]"]')],subjects=[...form.querySelectorAll('#scheduler-subjects [data-programme]')],branchFilter=document.getElementById('subject-branch-filter'),batchFilter=document.getElementById('subject-batch-filter'),summary=document.getElementById('scope-selection-summary');function selected(selector){return new Set([...form.querySelectorAll(selector+':checked')].map(input=>input.value));}function syncBatchScope(event){if(event?.target?.matches('input[name="programme_ids[]"]')){const programme=event.target.value,related=batchInputs.filter(input=>input.dataset.programme===programme);if(!event.target.checked)related.forEach(input=>input.checked=false);else if(!related.some(input=>input.checked))related.forEach(input=>input.checked=true);}if(event?.target?.matches('input[name="batch_ids[]"]')&&event.target.checked){programmeInputs.find(input=>input.value===event.target.dataset.programme).checked=true;}const programmes=selected('input[name="programme_ids[]"]'),batches=selected('input[name="batch_ids[]"]'),semesters=selected('input[name="semesters[]"]');[...batchFilter.options].forEach((option,index)=>{if(index===0)return;option.hidden=!batches.has(option.value)||(branchFilter.value!==''&&option.dataset.programme!==branchFilter.value);});if(batchFilter.selectedOptions[0]?.hidden)batchFilter.value='';let available=0,chosen=0;subjects.forEach(label=>{const input=label.querySelector('input'),batchMatch=label.dataset.batch==='0'||batches.has(label.dataset.batch),eligible=programmes.has(label.dataset.programme)&&semesters.has(label.dataset.semester)&&batchMatch,filtered=(branchFilter.value!==''&&label.dataset.programme!==branchFilter.value)||(batchFilter.value!==''&&label.dataset.batch!==batchFilter.value);input.disabled=!eligible;label.hidden=!eligible||filtered;if(eligible){available++;if(input.checked)chosen++;}});document.getElementById('available-subject-count').textContent=available;document.getElementById('selected-subject-count').textContent=chosen;document.getElementById('subject-scope-empty').hidden=available>0;if(programmes.size&&batches.size&&semesters.size)summary.textContent=programmes.size+' branch'+(programmes.size===1?'':'es')+', '+batches.size+' batch'+(batches.size===1?'':'es')+', '+semesters.size+' semester'+(semesters.size===1?'':'s')+', '+chosen+' paper'+(chosen===1?'':'s');}programmeInputs.forEach(input=>{if(input.checked&&!batchInputs.some(batch=>batch.dataset.programme===input.value&&batch.checked))batchInputs.filter(batch=>batch.dataset.programme===input.value).forEach(batch=>batch.checked=true);});form.addEventListener('change',event=>{if(event.target.matches('input[name="programme_ids[]"],input[name="batch_ids[]"],input[name="semesters[]"]'))queueMicrotask(()=>syncBatchScope(event));});branchFilter.addEventListener('change',()=>syncBatchScope());batchFilter.addEventListener('change',()=>syncBatchScope());document.getElementById('select-visible-subjects').addEventListener('click',()=>queueMicrotask(()=>syncBatchScope()));document.getElementById('clear-visible-subjects').addEventListener('click',()=>queueMicrotask(()=>syncBatchScope()));syncBatchScope();})();</script>
